select p.id id, p.seller_id sellerId, p.category_id categoryId, p.title title, p.price price, p.images images, p.description description, p.condition_level conditionLevel, p.is_flash_sale isFlashSale, p.flash_start_time flashStartTime, p.audit_status auditStatus, p.audit_note auditNote, p.status status, p.update_time updateTime, c.category_name categoryName from product p left join category c on p.category_id = c.id
and p.category_id = #{categoryId}
and p.title like concat('%', #{title}, '%')
and p.status = #{status}
and p.audit_status = #{auditStatus}
and p.seller_id = #{sellerId}
order by p.create_time desc, p.id desc

